class Solution {
public:
    int lengthOfLastWord(string s) {
        int n=s.size();
        int tail=n-1;
        while(tail>=0 and s[tail]==' ')
        {
            tail--;
        }
        int len=0;
        while(tail>=0 and s[tail]!=' ')
        {
            len+=1;
            tail--;
        }
        return len;
    }
};

